TCB_t user_tasks[5] ; //IDLE task , T1 , T2 , T3 , T4

uint32_t current_task = 1 ;  //task1 initially
uint32_t g_tick_count = 0 ;

void idle_task(){
	while(1);
}


void init_tasks_stack(){

	for(int x = 0 ;  x < 5 ; x++  ){
		user_tasks[x].current_state = TASK_RUNNING_STATE ;
	}

	user_tasks[0].psp_value = IDLE_STACK ;
	user_tasks[1].psp_value = T1_STACK ;
	user_tasks[2].psp_value = T2_STACK ;
	user_tasks[3].psp_value = T3_STACK ;
	user_tasks[4].psp_value = T4_STACK ;

	user_tasks[0].task_handler = (uint32_t)idle_task;
	user_tasks[1].task_handler = (uint32_t)task1_handler;
	user_tasks[2].task_handler = (uint32_t)task2_handler;
	user_tasks[3].task_handler = (uint32_t)task3_handler;
	user_tasks[4].task_handler = (uint32_t)task4_handler;


	uint32_t * pPSP ;

	for(int i = 0 ;   i<5 ; i++ ){    //from idle_task to task4 initially


		pPSP =  (uint32_t*)  ( user_tasks[i].psp_value )   ;

		pPSP -- ;
		*pPSP =  0x01000000 ; //xPSR on the stack frame initially

		pPSP -- ;
		*pPSP =  user_tasks[i].task_handler ;   //PC on the stack frame initially

		pPSP -- ;
		*pPSP =  0 ;         //LR on the stack frame initially

		for(int j = 0  ;   j<13   ; j++    ){
			pPSP --  ;
			*pPSP =  0 ;   // GPRs R0-R12 on the stack frame initially
		}

		user_tasks[i].psp_value  =   (uint32_t)  pPSP ;

	}
}

void task_delay(uint32_t tick_count){   //input is in ms

	__asm volatile ("mov r0,#0x01");
	__asm volatile ("msr primask , r0 ");  //disabling all interrupts to avoid race conditions of
										   //thread mode and handler mode code



	if(current_task){
		user_tasks[current_task].block_count = g_tick_count + tick_count ;
		user_tasks[current_task].current_state = TASK_BLOCKED_STATE ;

		uint32_t * pICSR = (uint32_t*) 0xE000ED04   ;
		//Interrupt control and state register (register of SCB)
		*pICSR |=  (1 << 28) ; //pending the pendsv exception
	}

	__asm volatile ("mov r0,#0x00");
	__asm volatile ("msr primask , r0 "); //enabling the interrupts

}




