void save_psp_value(uint32_t  psp  ){
	user_tasks[current_task].psp_value =  psp  ;
}

void update_current_task(){
	int state = TASK_BLOCKED_STATE ;
	for(int i = 0  ;   i<5 ; i++  ){
		current_task++;
		current_task %= 5 ;
		state = user_tasks[current_task].current_state ;
		if (    (state == TASK_RUNNING_STATE  )   && (current_task != 0)      )
			break ;
	}

	if(state !=   TASK_RUNNING_STATE){
		current_task =  0 ;
	}
}

uint32_t get_psp_val(){
	return user_tasks[current_task].psp_value ;
}

__attribute__((naked))void PendSV_Handler(){

	//printf("pendsv--- \n");

	__asm volatile("push {lr}") ;


	__asm volatile("mrs r0 , psp ");
	__asm volatile("stmdb  r0! , {r4-r11}    ") ;
	__asm volatile("bl save_psp_value");


	__asm volatile("bl update_current_task");


	__asm volatile("bl get_psp_val");
	__asm volatile("ldmia  r0! ,  {r4-r11}   ") ;
	__asm volatile("msr psp , r0 ");



	__asm volatile("pop {lr}");
	__asm volatile("bx lr") ;


}


void SysTick_Handler(){
	//printf("systick----- \n");
	//x = x+1 ;
	//printf("%lu \n" , x );

	g_tick_count++ ;

	for(int i = 1 ;  i<5 ; i++  ){
		if(user_tasks[i].current_state  != TASK_RUNNING_STATE   ){
			if(user_tasks[i].block_count  == g_tick_count  ){
				user_tasks[i].current_state = TASK_RUNNING_STATE ;
			}
		}
	}


	uint32_t * pICSR = (uint32_t*) 0xE000ED04   ;
	//Interrupt control and state register (register of SCB)
	*pICSR |=  (1 << 28) ; //pending the pendsv exception


}

